using System.Text.Json;
using FactorioModStudio.Core.Lua;

namespace FactorioModStudio.Core;

/// <summary>
/// Builds a <see cref="ModOverview"/> for a mod directory: files by category, prototypes and recipes it defines,
/// existing prototypes it touches, locale languages and validation findings.
/// The Lua analysis is static and heuristic: copies made with table.deepcopy or the building-block helpers are listed with
/// what the file changes, prototypes generated by loops or other functions are not, and the overview says how many such
/// entries were skipped.
/// </summary>
public static class ModInspector
{
    private const long MaxLuaFileBytes = 3 * 1024 * 1024;

    private static readonly HashSet<string> GraphicsExtensions = new(StringComparer.OrdinalIgnoreCase) { ".png", ".jpg", ".jpeg", ".gif", ".bmp", ".tga", ".dds" };
    private static readonly HashSet<string> SoundExtensions = new(StringComparer.OrdinalIgnoreCase) { ".ogg", ".wav", ".mp3", ".flac" };
    private static readonly HashSet<string> TextExtensions = new(StringComparer.OrdinalIgnoreCase) { ".txt", ".md" };

    private static readonly string[] DefaultNameSections =
    {
        "item-name", "entity-name", "fluid-name", "recipe-name", "technology-name",
        "equipment-name", "tile-name", "virtual-signal-name", "item-group-name"
    };

    public static ModOverview Inspect(string modDirectory, bool validate = true)
    {
        var root = Path.GetFullPath(modDirectory);
        var notes = new List<string>();

        var info = ReadSummary(root, out var modName);
        var relativePaths = ModFiles.Enumerate(root);

        var references = ModReferences.Analyze(root, modName, relativePaths);

        var files = new List<ModFileEntry>(relativePaths.Count);
        foreach (var relative in relativePaths)
        {
            var size = SafeLength(Path.Combine(root, relative.Replace('/', Path.DirectorySeparatorChar)));
            files.Add(new ModFileEntry(relative, size, Categorize(relative), RoleOf(relative))
            {
                Unused = references.Unused.TryGetValue(relative, out var unused) ? unused : null
            });
        }

        var languages = LocaleData.Languages(root);
        var locale = LocaleData.Load(root, languages.Contains("en") ? "en" : languages.FirstOrDefault() ?? "en");

        var prototypes = new List<PrototypeInfo>();
        var recipes = new List<RecipeInfo>();
        var touched = new Dictionary<string, TouchedPrototype>(StringComparer.Ordinal);
        var dynamic = 0;
        var skipped = 0;
        var blocks = new List<BlockSummary>();

        foreach (var file in files.Where(f => f.Category == "script"))
        {
            if (file.Size > MaxLuaFileBytes) { skipped++; continue; }

            string source;
            try { source = File.ReadAllText(Path.Combine(root, file.Path.Replace('/', Path.DirectorySeparatorChar))); }
            catch (IOException) { skipped++; continue; }
            catch (UnauthorizedAccessException) { skipped++; continue; }

            var scan = PrototypeScanner.Scan(source);
            dynamic += scan.DynamicEntries;
            if (BlockProperties.IsBlock(source))
                blocks.Add(new BlockSummary(file.Path, BlockProperties.TitleOf(source), scan.Prototypes.Select(p => p.Name).Distinct(StringComparer.Ordinal).ToList(), BlockOperations.NeedsUpgrade(source)));

            foreach (var raw in scan.Prototypes)
            {
                var display = DisplayName(locale, raw.Type, raw.Name);
                prototypes.Add(new PrototypeInfo(raw.Type, raw.Name, display, IconOf(raw.Table, modName), file.Path, raw.Line) { CopyOf = raw.CopyOf });
                if (raw.Type == "recipe") recipes.Add(ToRecipe(raw, display, file.Path));
            }

            foreach (var touch in scan.Touched)
                touched.TryAdd($"{touch.Type}/{touch.Name}", new TouchedPrototype(touch.Type, touch.Name, file.Path, touch.Line));
        }

        if (skipped > 0) notes.Add($"{skipped} Lua file(s) were skipped (unreadable or larger than {MaxLuaFileBytes / 1024 / 1024} MB).");
        if (dynamic > 0)
            notes.Add($"{dynamic} entr{(dynamic == 1 ? "y" : "ies")} passed to data:extend could not be resolved statically (variables or function calls), so the prototype and recipe lists may be incomplete.");

        // Broken asset paths and requires (FMS030-032) come from the validator, which runs the same ModReferences analysis.
        var issues = validate ? ModValidator.Validate(root).Issues : Array.Empty<ValidationIssue>();

        return new ModOverview(
            info,
            files,
            prototypes.OrderBy(p => p.Type, StringComparer.Ordinal).ThenBy(p => p.Name, StringComparer.Ordinal).ToList(),
            recipes.OrderBy(r => r.Name, StringComparer.Ordinal).ToList(),
            touched.Values.OrderBy(t => t.Type, StringComparer.Ordinal).ThenBy(t => t.Name, StringComparer.Ordinal).ToList(),
            languages,
            dynamic,
            issues,
            notes)
        {
            LocaleCoverage = LocaleChecker.Coverage(root),
            Blocks = blocks.OrderBy(b => b.File, StringComparer.Ordinal).ToList()
        };
    }

    public static string Categorize(string relativePath)
    {
        var ext = Path.GetExtension(relativePath);
        if (ext.Equals(".lua", StringComparison.OrdinalIgnoreCase)) return "script";
        if (ext.Equals(".cfg", StringComparison.OrdinalIgnoreCase) && relativePath.StartsWith("locale/", StringComparison.OrdinalIgnoreCase)) return "locale";
        if (GraphicsExtensions.Contains(ext)) return "graphics";
        if (SoundExtensions.Contains(ext)) return "sound";
        if (ext.Equals(".json", StringComparison.OrdinalIgnoreCase)) return "data";
        if (TextExtensions.Contains(ext)) return "text";
        return "other";
    }

    public static string? RoleOf(string relativePath)
    {
        if (relativePath.StartsWith("migrations/", StringComparison.OrdinalIgnoreCase) &&
            relativePath.EndsWith(".lua", StringComparison.OrdinalIgnoreCase))
            return "Migration script";

        return relativePath.ToLowerInvariant() switch
        {
            "settings.lua" => "Settings stage: define mod settings",
            "settings-updates.lua" => "Settings stage: updates",
            "settings-final-fixes.lua" => "Settings stage: final fixes",
            "data.lua" => "Data stage: define prototypes",
            "data-updates.lua" => "Data stage: update prototypes",
            "data-final-fixes.lua" => "Data stage: final fixes",
            "control.lua" => "Runtime: event handlers and game logic",
            _ => null
        };
    }

    private static ModSummary? ReadSummary(string root, out string? name)
    {
        name = null;
        var path = Path.Combine(root, "info.json");
        if (!File.Exists(path)) return null;

        try
        {
            var info = ModInfo.Load(path);
            name = info.Name;
            return new ModSummary(info.Name, info.Version, info.Title, info.Author, info.Description, info.FactorioVersion, info.RawDependencies);
        }
        catch (JsonException)
        {
            return null; // the validator reports this
        }
    }

    private static long SafeLength(string path)
    {
        try { return new FileInfo(path).Length; }
        catch (IOException) { return 0; }
    }

    private static string? DisplayName(LocaleData locale, string type, string name)
    {
        var sections = type switch
        {
            "recipe" => new[] { "recipe-name", "item-name", "fluid-name", "entity-name" },
            "technology" => new[] { "technology-name" },
            "fluid" => new[] { "fluid-name" },
            _ => DefaultNameSections
        };

        foreach (var section in sections)
            if (locale.Find(section, name) is { } text) return text;
        return null;
    }

    private static string? IconOf(LuaTable table, string? modName)
    {
        var icon = table.String("icon")
                   ?? (table.Table("icons")?.Items.FirstOrDefault() as LuaTable)?.String("icon");
        if (icon is null || modName is null) return null;

        var prefix = $"__{modName}__/";
        return icon.StartsWith(prefix, StringComparison.Ordinal) ? icon[prefix.Length..] : null;
    }

    private static RecipeInfo ToRecipe(RawPrototype raw, string? displayName, string file)
    {
        var table = raw.Table;

        // Factorio 1.1 recipes may keep their body under "normal" / "expensive".
        var body = table.Fields.ContainsKey("ingredients") || table.Fields.ContainsKey("results") || table.Fields.ContainsKey("result")
            ? table
            : table.Table("normal") ?? table;

        var ingredients = ReadItems(body.Table("ingredients"));

        IReadOnlyList<RecipeItem> results;
        if (body.Table("results") is { } resultList)
            results = ReadItems(resultList);
        else if (body.String("result") is { } single)
            results = new[] { new RecipeItem("item", single, body.Number("result_count") ?? 1) };
        else
            results = Array.Empty<RecipeItem>();

        return new RecipeInfo(
            raw.Name,
            displayName,
            table.String("category"),
            body.Number("energy_required") ?? table.Number("energy_required"),
            ingredients,
            results,
            file,
            raw.Line);
    }

    private static IReadOnlyList<RecipeItem> ReadItems(LuaTable? list)
    {
        var items = new List<RecipeItem>();
        if (list is null) return items;

        foreach (var entry in list.Items.OfType<LuaTable>())
        {
            if (entry.String("name") is { } named)
            {
                items.Add(new RecipeItem(entry.String("type") ?? "item", named, entry.Number("amount")));
            }
            else if (entry.Items.Count > 0 && entry.Items[0] is LuaString positional)
            {
                double? amount = entry.Items.Count > 1 && entry.Items[1] is LuaNumber n ? n.Value : null;
                items.Add(new RecipeItem("item", positional.Value, amount));
            }
        }

        return items;
    }
}
